@if(\App\Modules\User\Services\WorkspacePermissions::userCan('projects.create'))
<style>
.folder-create-dialog{width:min(600px,calc(100vw - 32px));max-height:85vh;overflow:auto;margin:auto;padding:24px;border:1px solid var(--border-soft);border-radius:20px;background:var(--bg-card);color:var(--text-primary);box-shadow:0 24px 80px #10182e33}.folder-create-dialog::backdrop{background:#10182e80;backdrop-filter:blur(3px)}.folder-create-dialog header,.folder-create-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.folder-create-dialog h2{font-size:20px;font-weight:700}.folder-create-dialog p{color:var(--text-muted);font-size:13px;margin-top:6px}.folder-create-dialog .fc-field{display:flex;flex-direction:column;gap:8px;margin-top:20px;font-size:13px}.folder-create-dialog input[type=text],.folder-create-dialog textarea{width:100%;padding:11px 12px;border:1px solid var(--border-strong);border-radius:11px;color:var(--text-primary);background:var(--bg-card);font:inherit}.folder-create-dialog input:focus-visible,.folder-create-dialog textarea:focus-visible,.folder-create-dialog button:focus-visible{outline:2px solid var(--accent,#3d6bff);outline-offset:3px}.fc-swatches{display:flex;flex-wrap:wrap;gap:10px}.fc-swatches button,.fc-custom{width:36px;height:36px;border-radius:11px;position:relative}.fc-swatches button[aria-pressed=true]{outline:2px solid var(--text-primary);outline-offset:3px}.fc-custom{display:grid;place-items:center;border:1px dashed var(--border-strong);overflow:hidden;cursor:pointer}.fc-custom input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.fc-preview{display:flex;gap:12px;align-items:center;margin-top:14px;font-size:12px;color:var(--text-muted)}.folder-create-dialog footer{justify-content:flex-end;margin-top:24px}.fc-button{min-height:40px;padding:9px 16px;border-radius:11px;border:1px solid var(--border-strong);font-size:13px;font-weight:600}.fc-submit{background:var(--accent,#3d6bff);color:white;border-color:var(--accent,#3d6bff)}.folder-create-dialog button:disabled{opacity:.5;cursor:wait}
</style>
<div x-data="folderCreateModal()" @open-folder-create.window="open()">
<dialog x-ref="dialog" data-folder-create-dialog class="folder-create-dialog" @cancel="if(busy)$event.preventDefault()" @click="if($event.target===$refs.dialog&&!busy)$refs.dialog.close()">
<form @submit.prevent="save()">
<header><h2>Create folder</h2><button type="button" @click="$refs.dialog.close()" :disabled="busy" aria-label="Close new folder">×</button></header>
<p>Bring content, knowledge and work into one project.</p>
<label class="fc-field">Name *<input type="text" x-ref="name" x-model="name" required maxlength="255" placeholder="e.g. Product launch" :disabled="busy"></label>
<div class="fc-field"><span>Folder color</span><div class="fc-swatches">@foreach(\App\Modules\User\Controllers\ProjectController::COLORS as $swatch)<button type="button" @click="color=@js($swatch)" style="background:{{ $swatch }}" :aria-pressed="color===@js($swatch)" aria-label="Folder color {{ $swatch }}" :disabled="busy"></button>@endforeach<label class="fc-custom"><i class="fas fa-eye-dropper" aria-hidden="true"></i><input type="color" x-model="color" aria-label="Custom folder color" :disabled="busy"></label></div><div class="fc-preview"><svg viewBox="0 0 96 72" width="56" height="44" aria-hidden="true"><path d="M6 14 a6 6 0 0 1 6-6 h22 l8 8 h42 a6 6 0 0 1 6 6 v4 H6 Z" :fill="color" opacity=".75"/><rect x="6" y="22" width="84" height="44" rx="6" :fill="color"/><rect x="6" y="22" width="84" height="10" rx="5" fill="white" opacity=".18"/></svg>Preview</div></div>
<label class="fc-field">Description<textarea x-model="description" rows="3" maxlength="1000" placeholder="Optional description…" :disabled="busy"></textarea></label>
<p x-show="error" x-text="error" role="alert" style="color:var(--danger,#dc2626)"></p>
<footer><button type="button" class="fc-button" @click="$refs.dialog.close()" :disabled="busy">Cancel</button><button type="submit" class="fc-button fc-submit" :disabled="busy" x-text="busy?'Creating…':'Create folder'"></button></footer>
</form></dialog></div>
<script>
function folderCreateModal(){return{name:'',description:'',color:'#3b82f6',error:'',busy:false,
open(){if(this.$refs.dialog.open)return;this.name='';this.description='';this.color='#3b82f6';this.error='';this.$refs.dialog.showModal();this.$nextTick(()=>this.$refs.name.focus());},
async save(){if(this.busy)return;this.busy=true;this.error='';try{const response=await fetch(@js(route('user.projects.store')),{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({name:this.name,color:this.color,description:this.description})});if(!response.headers.get('content-type')?.includes('application/json'))throw Error('Your session changed. Refresh and sign in again.');const data=await response.json();if(!response.ok)throw Error(Object.values(data.errors||{}).flat()[0]||data.message||'Folder could not be created.');this.$refs.dialog.close();if(document.getElementById('folder-explorer'))window.dispatchEvent(new CustomEvent('folder-created',{detail:data.project}));else location.assign(@js(route('user.folders.index'))+'?folder='+data.project.id);}catch(e){this.error=e.message;}finally{this.busy=false;}}
};}
</script>
@endif
